import Foundation
import CRMCore
func runInboxLinkClientChecks(directory:URL) async throws -> Int {
    var count=0
    func expect(_ v:Bool,_ m:String) throws {guard v else {throw CheckFailure(message:m)};count += 1}
    let d=try JSONSerialization.jsonObject(with:Data(contentsOf:directory.appendingPathComponent("inbox-link-client.json"))) as! [String:Any],profiles=APIReadRepository(transport:FixtureTransport(directory:directory))
    func context(_ x:[String:Int])->InboxConversationFilesContext {InboxConversationFilesContext(business:x["business"]!,conversation:x["conversation"]!,epoch:x["epoch"]!,revision:x["revision"]!)}
    for row in d["source_cases"] as! [[String:Any]] {let value=InboxLinkClientSource.decode(Data((row["response_json"] as! String).utf8),context:context(row["context"] as! [String:Int]));try expect((value != nil)==row["valid"] as! Bool,"Link source client vs client_id/null/scope \(row["name"]!)");if let value {try expect(value.valid && Mirror(reflecting:value).children.count==3,"Generic source retained metadata/authority")}}
    let c=context(d["context"] as! [String:Int]),source=InboxLinkClientSource.decode(Data((d["source_json"] as! String).utf8),context:c)!,port=FixtureInboxLinkClientPort(directory:directory),auth=port.grants[0].authorization(for:c)!
    func candidate(_ row:[String:Any],source:InboxLinkClientSource) async -> InboxLinkClientCandidate? {
        func n(_ k:String)->Int {row[k] as! Int}
        guard let profile=try? await profiles.clientProfile(business:n("profile_business"),id:n("profile_id")) else {return nil}
        return InboxLinkClientCandidate(source:source,selected:ClientSearchProfileSelection(selection:ClientSearchSelection(context:ClientSearchContext(business:n("search_business"),epoch:n("search_epoch")),generation:n("selection_generation")),id:n("selected_id"),generation:n("profile_generation")),read:ClientReadSelection(business:n("read_business"),id:n("read_id"),revision:n("read_revision")),rawQuery:row["raw_query"] as! String,profile:profile)
    }
    for row in d["candidate_cases"] as! [[String:Any]] {let value=await candidate(row,source:source);try expect((value != nil)==row["valid"] as! Bool,"Qualified Client read/window/profile scope \(row["name"]!)");if let value {try expect(value.valid && SourceTextIdentity.same(value.rawQuery,row["raw_query"] as? String),"Qualified candidate lost raw query/identity")}}
    let first=(d["candidate_cases"] as! [[String:Any]])[0],choice=await candidate(first,source:source)!,review=InboxLinkClientReview(source:source,authorization:auth,candidate:choice,visit:1);var ledger=InboxLinkClientLedger();let a=ledger.begin(review)!,body=try JSONSerialization.jsonObject(with:a.preparedBody()) as! [String:Int]
    try expect(body==["client_id":1701] && a.path=="/api/inbox/conversations/901/link-client/" && a.query.isEmpty && a.headers.isEmpty,"Link invented body Client DTO/Business/version/key or query")
    for row in d["receipt_cases"] as! [[String:Any]] {let receipt=InboxLinkClientReceipt.decode(Data((row["response_json"] as! String).utf8),attempt:a);try expect((receipt != nil)==row["valid"] as! Bool,"Plain200 exact chosen client echo \(row["name"]!)")}
    try expect(ledger.begin(review)==nil && !ledger.acknowledge(auth,record:ledger.visible(auth)!),"Pending link repeated/acknowledged")
    ledger.complete(a,outcome:try await port.execute(a));let response=ledger.visible(auth)!;try expect(response.phase == .response && response.result?.source.client==1701 && response.attempt.review.source.client==701 && response.attempt.review.candidate==choice,"Fake link mutated original or lost qualified candidate")
    ledger.complete(a,outcome:.unknown);try expect(ledger.visible(auth)==response && ledger.acknowledge(auth,record:response) && ledger.records.count==1,"Late completion or known acknowledgement lost history")
    let second=ledger.begin(review)!;ledger.complete(second,outcome:.unknown);let unknown=ledger.visible(auth)!,next=InboxConversationFilesContext(business:101,conversation:901,epoch:2,revision:2),na=port.grants[0].authorization(for:next)!
    let matching=InboxLinkClientSource.decode(Data("{\"id\":901,\"business\":101,\"client\":1701,\"updated_at\":\"synthetic raw\"}".utf8),context:next)!
    var nextRow=first;nextRow["search_epoch"]=2;nextRow["read_revision"]=2;let newChoice=await candidate(nextRow,source:matching)!
    try expect(ledger.visible(na)==unknown && !ledger.acknowledge(na,record:unknown) && ledger.begin(InboxLinkClientReview(source:matching,authorization:na,candidate:newChoice,visit:2))==nil && ledger.records[1].attempt==second,"Matching link/GET/new read proved unknown or rebound original candidate")
    let other=SyntheticInboxLinkClientGrant(business:101,conversation:901,actor:6002,clientsUpdate:true,conversationsUpdate:true).authorization(for:next)!;try expect(ledger.visible(other)==nil && ledger.blocked(business:101,conversation:901) && !ledger.blocked(business:202,conversation:951),"Actor/Business changed link barrier/visibility")
    for grant in [SyntheticInboxLinkClientGrant(business:101,conversation:901,actor:5001,clientsUpdate:false,conversationsUpdate:true),SyntheticInboxLinkClientGrant(business:101,conversation:901,actor:5001,clientsUpdate:true,conversationsUpdate:false),SyntheticInboxLinkClientGrant(business:202,conversation:901,actor:5001,clientsUpdate:true,conversationsUpdate:true),SyntheticInboxLinkClientGrant(business:101,conversation:951,actor:5001,clientsUpdate:true,conversationsUpdate:true),SyntheticInboxLinkClientGrant(business:101,conversation:901,actor:0,clientsUpdate:true,conversationsUpdate:true)] {try expect(grant.authorization(for:c)==nil,"Missing one of two UPDATE grants/scope/actor invented authority")}
    for status in [201,400,403,409,500] {var l=InboxLinkClientLedger();let a=l.begin(review)!;l.complete(a,outcome:.response(status:status,data:Data("{}".utf8)));try expect(l.visible(auth)?.phase == .unknown && !l.acknowledge(auth,record:l.visible(auth)!),"Unexpected status inferred safe link retry")}
    var rejected=InboxLinkClientLedger();let ra=rejected.begin(review)!;rejected.complete(ra,outcome:.rejectedWithoutWrite);let rr=rejected.visible(auth)!;try expect(rr.phase == .rejected && rejected.acknowledge(auth,record:rr) && rejected.records.count==1,"Explicit no-write link rejection lost attempt")
    return count
}
